import{_ as a,o as t,c as s,a5 as o}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"持久化与持久恢复","description":"","frontmatter":{"title":"持久化与持久恢复","docId":"developer.storage","translationKey":"developer.storage","locale":"zh","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"7ec9d94e484af17e8e82aaaa2122cc47ecd206cf9306047795d6aaa72eea2edb","translationRevision":"1eebde56f068e9c54db4e6201a19caec1b093f1d229bd33d4953e7a027266391","order":60},"headers":[],"relativePath":"zh/developer/storage.md","filePath":"zh/developer/storage.md","lastUpdated":1794611623000}'),i={name:"zh/developer/storage.md"};function r(d,e,l,c,n,h){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="persistence-and-durable-recovery" tabindex="-1">持久化与持久恢复 <a class="header-anchor" href="#persistence-and-durable-recovery" aria-label="Permalink to &quot;持久化与持久恢复 {#persistence-and-durable-recovery}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目标与前置条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>通过所属服务修改持久状态，并保留可恢复结果。使用可丢弃配置，复制数据库前关闭其宿主，编辑版本化资源前阅读<a href="./control-api.html">控制元数据</a>。<code>TIKTOOLS_HOME</code> 选择应用根目录；<code>AppPaths</code> 解析数据及私有存储位置。</p><h2 id="identify-the-store" tabindex="-1">识别存储 <a class="header-anchor" href="#identify-the-store" aria-label="Permalink to &quot;识别存储 {#identify-the-store}&quot;">​</a></h2><p><code>crates/tiktools-core/src/paths.rs</code> 定义 <code>data/tiktok-points.db</code>、<code>data/tiktok-automation.db</code> 和 <code>data/tiktok-analytics.db</code>。SQLite 服务模块管理各自 schema。积分/观众和自动化定义拥有独立业务账本；统计是单独数据库，旧的双数据库图遗漏了它。</p><p>启动时，仅在目标不存在的情况下，才可将检出目录中的旧数据库复制到平台应用数据目录，绝不覆盖现有目标。原生执行变化期间，JSON 定义仍保持可读。不要通过删除用户配置或从 Vue 重写数据表来实现迁移。</p><h2 id="make-a-recoverable-change" tabindex="-1">进行可恢复的修改 <a class="header-anchor" href="#make-a-recoverable-change" aria-label="Permalink to &quot;进行可恢复的修改 {#make-a-recoverable-change}&quot;">​</a></h2><ol><li>找到服务事务及其 schema/迁移测试。</li><li>在领域支持的情况下，将业务变更、修订和必需日志/发件箱预留写入同一事务。</li><li>删除时保留修订墓碑。复用的记录 ID 不得接受删除前的编辑修订。</li><li>通过现有发件箱发布已提交的失效元数据；投递重试不得重复底层操作。</li><li>中断后重新打开同一私有测试主目录，并在尝试其他修改前解决原始命令。</li></ol><p>对已运行测试宿主的有用只读检查：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span></code></pre></div><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;预期结果与状态 {#expected-result-and-status}&quot;">​</a></h2><p>受支持的持久化工作流程、积分和所有者日志会跨重启保留原始结果。回执描述历史命令，当前状态应单独读取。Cloud 工作区存储添加来源/账户分区及代次检查，不会替代本地 SQLite 的权威性。并非所有外部效果或领域都具备同样的持久恢复覆盖。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;恢复方法 {#recovery}&quot;">​</a></h2><p>离线备份时，将 SQLite 文件与所有活动 WAL/SHM 文件一同保留。UI 超时不能证明已回滚。遇到 <code>revision_conflict</code>，保留草稿并比较新的读取结果。外部效果不确定时，检查保留的效果记录，不要重放事件流。各自边界见<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/paths.rs" target="_blank" rel="noreferrer">路径权威实现</a>及 <a href="./cloud.html">Cloud 恢复</a>。</p><h2 id="operational-details" tabindex="-1">运行细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;运行细节 {#operational-details}&quot;">​</a></h2><p>试验或备份前，使用 <code>tiktools api call system.info --json</code> 查看实际路径。<code>TIKTOOLS_HOME</code> 选择根目录；<code>TIKTOOLS_DATA_DIR</code>、<code>TIKTOOLS_PLUGINS_DIR</code>、<code>TIKTOOLS_PLUGIN_DATA_DIR</code>、<code>TIKTOOLS_PLUGIN_STORE_DIR</code>、<code>TIKTOOLS_LOG_DIR</code>、<code>TIKTOOLS_TEMP_DIR</code> 分别覆盖派生目录。相对路径基于启动工作目录。单独隔离 home 不会消除继承的覆盖变量，应先检查或取消它们。</p><p>Analytics 保存聚合数据并使用独立写入器：当前队列为 1,024，批次为 128，刷新期限 10 秒。数据库旁的 <code>*.pending.json</code> 路径由该数据库路径派生。启动时按批次 ID 重放保留内容并移除恢复文件，之后 <code>ready</code> 才允许新工作。恢复文件不可读或超过 16 MiB、数据库不可用或无法移除恢复文件时，保持禁止接收。请保留数据库及恢复文件，检查 <code>ready</code>、待处理计数和错误，修复前备份。不要删除待处理证据来掩盖故障；积分日志具有独立持久性契约。</p><p><code>system.info</code> 报告实际 home/dataDir；其他目录需按宿主真实启动环境解析，不能只查看另一终端。<code>system.health</code> 提供 Analytics ready/待处理及 LIVE 入口计数。</p>`,18)])])}const u=a(i,[["render",r]]);export{k as __pageData,u as default};
